package br.com.brindespro.portfolio;
import jakarta.persistence.*;import java.time.OffsetDateTime;
@Entity @Table(name="portfolio_projects") public class PortfolioProject {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id;@Column(nullable=false) public String name;@Column(nullable=false) public String segment;@Column(nullable=false) public String category;@Column(nullable=false,length=1000) public String description;@Column(nullable=false) public int quantity;@Column(name="lead_time",nullable=false) public String leadTime;@Column(name="finish_type",nullable=false) public String finishType;@Column(name="image_url",nullable=false,length=500) public String imageUrl;@Column(nullable=false) public boolean featured;@Column(nullable=false) public boolean active=true;@Column(name="created_at",nullable=false) public OffsetDateTime createdAt=OffsetDateTime.now();@Column(name="updated_at",nullable=false) public OffsetDateTime updatedAt=OffsetDateTime.now();protected PortfolioProject(){} }
